What is printed?

```js
function divide(a, b) {
  if (b === 0) {
    throw new Error("Cannot divide by zero");
  }
  return a / b;
}

try {
  console.log(divide(10, 2));
  console.log(divide(10, 0));
  console.log("after divides");
} catch (err) {
  console.log("caught:", err.message);
}
console.log("done");
```

